using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using SpatialWallpaper.Sdk;
using SpatialWallpaper.Sdk.Editor;
public static class PoolContentExport {
 public static void Run(){
  PlayerSettings.colorSpace=ColorSpace.Linear;PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64,false);PlayerSettings.SetGraphicsAPIs(BuildTarget.StandaloneWindows64,new[]{GraphicsDeviceType.Direct3D11});
  EditorSceneManager.OpenScene("Assets/Library/Scenes/pool.unity");var root=GameObject.Find("PoolContent").transform;
  var definition=new GameObject("SDK Author").AddComponent<SceneDefinition>();definition.contentRoot=root;definition.templateId="89f449e1-3615-4d1a-a5c8-cfd322b65891";definition.displayName="Pool";definition.authorFrame=new Vector3(.53f,.298125f,2);definition.licenseSource="Original local Pool assets; local validation only";
  string output=Environment.GetEnvironmentVariable("CONTENT_BUILD_OUTPUT");
  var info=new Newtonsoft.Json.Linq.JObject{["components"]=new Newtonsoft.Json.Linq.JArray(root.GetComponentsInChildren<MonoBehaviour>(true).Select(c=>c?c.GetType().Name:"missing-script")),["materials"]=new Newtonsoft.Json.Linq.JArray(root.GetComponentsInChildren<MeshRenderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().Select(m=>(Newtonsoft.Json.Linq.JToken)new Newtonsoft.Json.Linq.JObject{["name"]=m.name,["shader"]=m.shader.name,["shader_asset"]=AssetDatabase.GetAssetPath(m.shader)})),["meshes"]=new Newtonsoft.Json.Linq.JArray(root.GetComponentsInChildren<MeshFilter>(true).Select(f=>(Newtonsoft.Json.Linq.JToken)new Newtonsoft.Json.Linq.JObject{["name"]=f.name,["vertices"]=f.sharedMesh.vertexCount,["submeshes"]=f.sharedMesh.subMeshCount}))};File.WriteAllText(Path.Combine(output,"reports/pool-source-facts.json"),info.ToString());
  var sceneSettings=root.GetComponent<SceneRenderSettings>();if(!sceneSettings||!(sceneSettings.pipeline is UniversalRenderPipelineAsset))throw new InvalidOperationException("pool-pipeline-missing");var pipeline=(UniversalRenderPipelineAsset)sceneSettings.pipeline;GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;
  var camera=UnityEngine.Object.FindObjectsOfType<Camera>().Single(c=>c.name=="DisplayCamera");var framing=root.GetComponentsInChildren<DisplaySceneVolume>().Single();definition.authorFrame=Vector3.Scale(framing.size,framing.transform.lossyScale);
  ftLightmaps.RefreshFull();var maps=LightmapSettings.lightmaps;var mode=LightmapSettings.lightmapsMode;var renderers=root.GetComponentsInChildren<MeshRenderer>();var indices=renderers.Select(r=>r.lightmapIndex).ToArray();var offsets=renderers.Select(r=>r.lightmapScaleOffset).ToArray();var lightStates=root.GetComponentsInChildren<Light>().ToDictionary(l=>l,l=>l.bakingOutput);
  info["registered_lightmaps"]=maps.Length;info["lightmap_bindings"]=new Newtonsoft.Json.Linq.JArray(renderers.Select((r,i)=>(Newtonsoft.Json.Linq.JToken)new Newtonsoft.Json.Linq.JObject{["name"]=r.name,["index"]=indices[i]}));File.WriteAllText(Path.Combine(output,"reports/pool-source-facts.json"),info.ToString());
  foreach(var component in root.GetComponentsInChildren<MonoBehaviour>())if(component is BakeryDirectLight||component is BakerySkyLight||component is BakeryPointLight||component is BakeryLightmappedPrefab||component is ftLightmapsStorage||component is BakeryLightmapGroupSelector)UnityEngine.Object.DestroyImmediate(component);
  LightmapSettings.lightmaps=maps;LightmapSettings.lightmapsMode=mode;for(int i=0;i<renderers.Length;i++){renderers[i].lightmapIndex=indices[i];renderers[i].lightmapScaleOffset=offsets[i];}foreach(var state in lightStates)state.Key.bakingOutput=state.Value;
  var owned=new System.Collections.Generic.Dictionary<Material,Material>();Func<Material,Material> own=material=>{if(!owned.TryGetValue(material,out var result)){result=new Material(material);owned.Add(material,result);}return result;};foreach(var renderer in renderers)renderer.sharedMaterials=renderer.sharedMaterials.Select(own).ToArray();
  var oldAnimation=root.GetComponent<PoolAnimation>();var oldSurface=root.GetComponent<PoolMaterialState>();var oldReflection=root.GetComponentInChildren<PoolPlanarReflection>();if(!oldAnimation||!oldSurface||!oldReflection)throw new InvalidOperationException("pool-runtime-source-missing");
  var ring=oldAnimation.ring;var size=ring.GetComponent<MeshFilter>().sharedMesh.bounds.size;Vector3 axis=size.x<size.y&&size.x<size.z?Vector3.right:size.y<size.z?Vector3.up:Vector3.forward;var normal=ring.TransformDirection(axis);if(Vector3.Dot(normal,Vector3.up)<0)normal=-normal;ring.rotation=Quaternion.FromToRotation(normal,Vector3.up)*ring.rotation;float bottom=ring.GetComponent<Renderer>().bounds.min.y;ring.position+=Vector3.up*(oldSurface.waterSurface.position.y-.10f*oldSurface.waterSurface.lossyScale.x-bottom);
  var motion=ring.gameObject.AddComponent<TransformOscillation>();motion.position=new[]{new TransformHarmonic{amplitude=new Vector3(.04f,.045f,.03f),frequency=new Vector3(.31f,1.1f,.23f)},new TransformHarmonic{amplitude=new Vector3(0,.012f,0),frequency=new Vector3(0,1.73f,0)}};motion.rotation=new[]{new TransformHarmonic{amplitude=new Vector3(.55f,1.5f,.45f),frequency=new Vector3(.8f,.19f,.7f),phase=new Vector3(0,0,Mathf.PI/2)}};
  var surface=oldSurface.waterSurface.gameObject.AddComponent<SurfaceMaterialBinding>();surface.materials=owned.Values.Where(m=>m.HasProperty("_WaterLevel")||m.HasProperty("_DepthEnd")).ToArray();surface.depthPerScale=.12f/(.53f/11.2f);surface.causticsTiling=new Vector4(.2f,.2f,.3f,.3f);surface.Apply();
  var reflection=oldReflection.gameObject.AddComponent<PlanarReflection>();reflection.material=own(oldReflection.reflectionMaterial);reflection.resolutionScale=oldReflection.resolutionScale;reflection.excluded=renderers.Where(r=>r.gameObject.layer==4).Cast<Renderer>().ToArray();if(reflection.excluded.Length==0)throw new InvalidOperationException("pool-reflection-exclusions-missing");
  UnityEngine.Object.DestroyImmediate(oldAnimation);UnityEngine.Object.DestroyImmediate(oldSurface);UnityEngine.Object.DestroyImmediate(oldReflection);UnityEngine.Object.DestroyImmediate(sceneSettings);UnityEngine.Object.DestroyImmediate(framing);foreach(var demand in root.GetComponentsInChildren<ContinuousRenderDemand>())UnityEngine.Object.DestroyImmediate(demand);foreach(var lightData in root.GetComponentsInChildren<UniversalAdditionalLightData>())UnityEngine.Object.DestroyImmediate(lightData);
  GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;var presentation=root.gameObject.AddComponent<ScenePresentationSettings>();presentation.customBackground=true;presentation.backgroundColor=camera.backgroundColor;presentation.customClipDepth=true;presentation.clipDepth=camera.GetComponent<WindowProjection>().contentDepth;presentation.customCamera=true;presentation.hdr=camera.allowHDR;presentation.msaa=camera.allowMSAA?pipeline.msaaSampleCount:1;
  if(RenderSettings.ambientMode!=AmbientMode.Trilight)throw new InvalidOperationException("pool-source-ambient-mode-changed");presentation.customAmbientGradient=true;presentation.ambientSky=RenderSettings.ambientSkyColor;presentation.ambientEquator=RenderSettings.ambientEquatorColor;presentation.ambientGround=RenderSettings.ambientGroundColor;
  presentation.profile=PresentationProfile.Forward;var cameraData=camera.GetUniversalAdditionalCameraData();presentation.opaqueTexture=cameraData.requiresColorTexture;presentation.depthTexture=cameraData.requiresDepthTexture;presentation.cameraPostProcessing=cameraData.renderPostProcessing;
  // Missing source overrides contribute no effect, rather than the SDK inspector preset.
  presentation.bloom=Vector3.zero;presentation.aces=false;presentation.exposure=0;presentation.saturation=0;presentation.vignette=Vector2.zero;
  var volume=root.GetComponentInChildren<Volume>();if(volume){var profile=volume.sharedProfile;presentation.postProcessing=true;if(profile.TryGet<Bloom>(out var bloom))presentation.bloom=new Vector3(bloom.threshold.value,bloom.intensity.value,bloom.scatter.value);if(profile.TryGet<Tonemapping>(out var tone))presentation.aces=tone.mode.value==TonemappingMode.ACES;if(profile.TryGet<ColorAdjustments>(out var color)){presentation.exposure=color.postExposure.value;presentation.saturation=color.saturation.value;}if(profile.TryGet<Vignette>(out var vignette))presentation.vignette=new Vector2(vignette.intensity.value,vignette.smoothness.value);foreach(var component in profile.components)if(!(component is Bloom||component is Tonemapping||component is ColorAdjustments||component is Vignette))throw new InvalidOperationException("unsupported-pool-grade");UnityEngine.Object.DestroyImmediate(volume);}
  var textures=owned.Values.SelectMany(m=>m.GetTexturePropertyNames().Select(m.GetTexture)).Concat(maps.SelectMany(m=>new Texture[]{m.lightmapColor,m.lightmapDir,m.shadowMask})).Where(t=>t).Distinct();File.WriteAllText(Path.Combine(output,"reports/pool-source-textures.json"),new Newtonsoft.Json.Linq.JArray(textures.Select(t=>(Newtonsoft.Json.Linq.JToken)new Newtonsoft.Json.Linq.JObject{["name"]=t.name,["asset"]=AssetDatabase.GetAssetPath(t),["width"]=t.width,["height"]=t.height,["mips"]=t.mipmapCount,["format"]=t.graphicsFormat.ToString(),["kind"]=t.GetType().Name})).ToString());
  try{string id=ScenePackageExporter.Export(definition,Path.Combine(output,"Pool.spatial"),ExportMode.LocalValidation);File.WriteAllText(Path.Combine(output,"pool-build-id.txt"),id);}
  catch(Exception error){File.WriteAllText(Path.Combine(output,"reports/pool-export-failure.json"),new Newtonsoft.Json.Linq.JObject{["passed"]=false,["error"]=error.Message}.ToString());throw;}
 }
}
